local help = {
 {"Your hero's frame: health, power and level. Drag the green handle to place it; its size and scale are below.", "Marco de tu héroe: salud, poder y nivel. Arrastra el control verde para colocarlo; abajo están su tamaño y escala.", "Cadre de votre héros : santé, puissance et niveau. Faites glisser la poignée verte pour le placer ; sa taille et son échelle sont ci-dessous.", "Das Fenster deines Helden mit Gesundheit, Kraft und Stufe. Ziehe den grünen Griff zum Verschieben; Größe und Skalierung stellst du unten ein."},
 {"Your friends' frames in co-op. They show now even if you're alone, so you can place them. Choose a column or a row, face plates or thin lines, and whether you join them.", "Marcos de tus amigos en cooperativo. Se muestran incluso si estás solo para que puedas colocarlos. Elige columna o fila, retratos o líneas finas, y si quieres unirte al grupo.", "Les cadres de vos amis en coopération. Ils s’affichent même si vous êtes seul afin de pouvoir les placer. Choisissez une colonne ou une ligne, des portraits ou des lignes fines, et si vous rejoignez le groupe.", "Fenster deiner Freunde im Koop. Sie werden auch allein angezeigt, damit du sie platzieren kannst. Wähle Spalte oder Zeile, Porträts oder dünne Linien und ob du der Gruppe beitrittst."},
 {"Your spells. Drag to place it; its size, and turning it upright, are below.", "Tus hechizos. Arrástralos para colocarlos; abajo puedes cambiar su tamaño y orientación.", "Vos sorts. Faites-les glisser pour les placer ; leur taille et leur orientation se règlent ci-dessous.", "Deine Zauber. Ziehe sie an die gewünschte Stelle; Größe und Ausrichtung stellst du unten ein."},
 {"The enemy the game has picked for you.", "El enemigo que el juego ha seleccionado para ti.", "L’ennemi choisi pour vous par le jeu.", "Der Gegner, den das Spiel für dich ausgewählt hat."},
 {"Your experience bar. It can stand upright too (below).", "Tu barra de experiencia. También puede ponerse en vertical (abajo).", "Votre barre d’expérience. Elle peut aussi être verticale (ci-dessous).", "Deine Erfahrungsleiste. Sie kann auch senkrecht stehen (siehe unten)."},
 {"Your buffs and debuffs. Below, stack them in a column and choose which way they grow. Attached to the target frame, they move and scale with it instead.", "Tus beneficios y perjuicios. Abajo puedes apilarlos en una columna y elegir su dirección. Si se vinculan al marco del objetivo, se moverán y escalarán con él.", "Vos améliorations et affaiblissements. Ci-dessous, empilez-les en colonne et choisissez leur direction. Attachés au cadre de la cible, ils se déplacent et changent d’échelle avec lui.", "Deine Stärkungen und Schwächungen. Unten kannst du sie stapeln und ihre Wachstumsrichtung wählen. Am Zielfenster bewegen und skalieren sie sich mit diesem."},
 {"The minimap, with its pins.", "El minimapa y sus marcadores.", "La minicarte et ses repères.", "Die Minikarte mit Markierungen."},
 {"The chat window, its tab and the box you type in move together.", "La ventana de chat, su pestaña y el cuadro de escritura se mueven juntos.", "La fenêtre de discussion, son onglet et la zone de saisie se déplacent ensemble.", "Chatfenster, Reiter und Eingabefeld werden gemeinsam verschoben."},
 {"Where tooltips appear, and how wide they are. Each one is as tall as its own text.", "Dónde aparecen las descripciones emergentes y su anchura. Cada una se adapta a la altura de su texto.", "Emplacement et largeur des infobulles. Chacune s’adapte à la hauteur de son texte.", "Position und Breite der Tooltips. Jeder Tooltip passt sich der Höhe seines Textes an."},
 {"The movable Level Up button and its store toggle.", "El botón móvil Subir de nivel y su control de almacenamiento.", "Le bouton Niveau supérieur déplaçable et sa commande de stockage.", "Der verschiebbare Stufenaufstieg-Button und sein Speicher-Schalter."},
 {"Your build spells, with your worn jewelry joined under them.", "Tus hechizos de la build, con las joyas equipadas debajo.", "Vos sorts de configuration, avec vos bijoux équipés regroupés en dessous.", "Deine Build-Zauber mit dem darunter angeordneten getragenen Schmuck."},
 {"The meter. Its corner grip resizes it any time.", "El medidor. Puedes cambiar su tamaño arrastrando la esquina.", "Le compteur. Sa poignée d’angle permet de le redimensionner à tout moment.", "Der Zähler. Über den Eckgriff kannst du jederzeit seine Größe ändern."},
 {"Run time and the next boss.", "Tiempo de partida y siguiente jefe.", "Durée de la partie et prochain boss.", "Rundenzeit und nächster Boss."},
 {"Boss, Guardian and elite health bars.", "Barras de salud de jefes, guardianes y élites.", "Barres de vie des boss, gardiens et élites.", "Lebensleisten von Bossen, Wächtern und Elitegegnern."},
 {"Your run's tally.", "Resumen de tu partida.", "Le récapitulatif de votre partie.", "Die Übersicht deiner Runde."},
 {"Where event announcements appear.", "Dónde aparecen los anuncios de eventos.", "Emplacement des annonces d’événement.", "Position der Ereignismeldungen."},
 {"The bar shown while you bring a friend back.", "La barra que aparece mientras revives a un amigo.", "La barre affichée pendant que vous réanimez un ami.", "Die Leiste, die beim Wiederbeleben eines Freundes angezeigt wird."},
 {"Your real-world clock: 12/24-hour, its background and daylight saving are below.", "Tu reloj local: abajo puedes elegir formato de 12/24 horas, fondo y horario de verano.", "Votre horloge locale : format 12/24 heures, arrière-plan et heure d’été se règlent ci-dessous.", "Deine lokale Uhr: 12/24-Stunden-Format, Hintergrund und Sommerzeit stellst du unten ein."},
 {"Optional: takes every minimap button and the day/night moon off the map into one row you can drag anywhere. Off, the buttons stay on the map's ring.", "Opcional: reúne todos los botones del minimapa y el icono día/noche en una fila móvil. Si está desactivado, permanecen en el borde del mapa.", "Facultatif : regroupe les boutons de la minicarte et l’icône jour/nuit dans une rangée déplaçable. Désactivés, les boutons restent sur le bord de la carte.", "Optional: Verschiebt alle Minikarten-Buttons und das Tag/Nacht-Symbol in eine frei bewegliche Leiste. Ausgeschaltet bleiben sie am Kartenrand."},
 {"Your newest hits and heals, each with its spell icon. Crits stand out.", "Tus golpes y sanaciones recientes, cada uno con su icono. Los críticos destacan.", "Vos derniers coups et soins, chacun avec son icône de sort. Les critiques ressortent.", "Deine neuesten Treffer und Heilungen mit Zauber-Icon. Kritische Treffer heben sich ab."},
};
for i = 1, table.getn(help) do local row = help[i]; SS.LOCALE_TEXT.esES[row[1]] = row[2]; SS.LOCALE_TEXT.frFR[row[1]] = row[3]; SS.LOCALE_TEXT.deDE[row[1]] = row[4]; end
function SS.LocaleCode()
 local locale=GetLocale and GetLocale() or "enUS";
 if ( SS.LOCALE_TEXT[locale] ) then return locale; end
 local language=string.sub(tostring(locale),1,2);
 for code in pairs(SS.LOCALE_TEXT) do if ( string.sub(code,1,2)==language ) then return code; end end
 return "enUS";
end
function SS.T(text)
 if ( type(text)~="string" ) then return text; end
 local translations=SS.LOCALE_TEXT[SS.LocaleCode()];
 return (translations and translations[text]) or text;
end
function SS.TranslateRecord(record)
 if ( type(record)~="table" ) then return record; end
 for _,key in ipairs({"title","text","short","label","name"}) do
  if ( type(record[key])=="string" ) then record[key]=SS.T(record[key]); end
 end
 return record;
end
